As a small addition: Limits could be added to the config, so that opencode correctly displays the percentage of used tokens (and i guess it then also correctly knows when to do compaction).

```json
  "provider": {
    "github-copilot": {
      "models": {
        "gpt-5.3-codex": {
          "modalities": {
            "input": ["text", "image"],
            "output": ["text"]
          },
          "limit": {
            "context": 400000,
            "input": 272000,
            "output": 128000
          },
          "variants": {
            "low": {
              "reasoningEffort": "low",
              "reasoningSummary": "auto",
              "include": ["reasoning.encrypted_content"]
            },
            "medium": {
              "reasoningEffort": "medium",
              "reasoningSummary": "auto",
              "include": ["reasoning.encrypted_content"]
            },
            "high": {
              "reasoningEffort": "high",
              "reasoningSummary": "auto",
              "include": ["reasoning.encrypted_content"]
            },
            "xhigh": {
              "reasoningEffort": "xhigh",
              "reasoningSummary": "auto",
              "include": ["reasoning.encrypted_content"]
            }
          }
        }
      }
    }
  }
```

i was able to get codex 5.3 to show up for openrouter by adding the following to `~/.config/opencode/opencode.json`:

```json
{
  "$schema": "https://opencode.ai/config.json",
  "provider": {
    "openrouter": {
      "models": {
        "openai/gpt-5.3-codex": {
          "name": "GPT-5.3-Codex",
          "reasoning": true,
          "attachment": true,
          "tool_call": true,
          "structured_output": true,
          "cost": {
            "input": 1.75,
            "output": 14,
            "cache_read": 0.175
          },
          "limit": {
            "context": 400000,
            "output": 128000
          },
          "modalities": {
            "input": [
              "text",
              "image"
            ],
            "output": [
              "text"
            ]
          },
          "options": {
            "reasoningEffort": "medium",
            "reasoningSummary": "auto",
            "temperature": 1
          }
        }
      }
    }
  }
}
```
